import{c as t,Q as r,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const o="/assets/%E5%A4%B4%E5%BC%80%E9%94%80%E9%9A%8F%E5%90%AF%E5%8A%A8%E6%A0%B8%E6%95%B0%E7%9A%84%E5%8F%98%E5%8C%96.DiCD0ZZU.png",E=JSON.parse('{"title":"设置合适的核数和算子Kernel类型","description":"","frontmatter":{},"headers":[{"level":1,"title":"设置合适的核数和算子Kernel类型","slug":"设置合适的核数和算子kernel类型"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/头尾开销优化/设置合适的核数和算子Kernel类型.md","filePath":"guide/算子实践参考/SIMD算子性能优化/头尾开销优化/设置合适的核数和算子Kernel类型.md"}'),i={name:"guide/算子实践参考/SIMD算子性能优化/头尾开销优化/设置合适的核数和算子Kernel类型.md"};function a(s,e,_,p,c,g){return r(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="设置合适的核数和算子kernel类型" tabindex="-1">设置合适的核数和算子Kernel类型 <a class="header-anchor" href="#设置合适的核数和算子kernel类型" aria-label="Permalink to &quot;设置合适的核数和算子Kernel类型&quot;">​</a></h1><p>在算子执行过程中，可能会因为以下几个原因产生额外的启动开销或者头开销：</p><ol><li><strong>核启动</strong>：每个核在启动时需要进行初始化操作，加载必要的配置和资源。</li><li><strong>核取址TLB MISS</strong>：当核在访问内存时，如果Translation Lookaside Buffer（TLB）中没有对应的页表项，就需要从内存中加载页表项，这会导致额外的延迟。</li><li><strong>同地址访问冲突</strong>：由于硬件限制，多个核同时访问相同的内存地址时可能会发生冲突，导致额外的时延。</li><li><strong>变量资源初始化</strong>：在算子执行前，需要初始化一些变量和资源，这也可能带来额外的性能开销。</li></ol><p>头开销会随着使用的核数增加而增加。下图展示了这部分头开销随启动核数的变化情况。</p><p><strong>图 1</strong> 头开销随启动核数的变化<br><img src="'+o+'" alt="" title="头开销随启动核数的变化"></p><p>**对于整体耗时在微秒级别且单核计算量耗时较少的算子，可以通过减少启动核数并增加单核计算量的方式来获得性能提升。**这种优化方式的本质是在头开销耗时和单核计算量耗时之间进行权衡。为了达到最佳性能，开发者需要通过实践尝试，找到最合适的核数设置。</p><ul><li><p>对于自定义算子工程，可以在TilingFunc（算子工程提供的在Host侧计算Tiling的默认函数）中通过SetBlockDim接口来设置算子使用的核数，具体设置方法请参考SetBlockDim；对于Kernel直调工程，可以在&lt;&lt;&lt;&gt;&gt;&gt;调用时指定算子使用的核数。</p></li><li><p>此外，算子的Kernel类型也会影响算子启动的核数。以纯Vector算子为例，如果以混合启动的方式执行该算子，调度器会同时启动Vector核和Cube核。然而，此时Cube核并没有实际的计算指令，但仍会产生核启动和核初始化的头开销。因此，建议设置合适的Kernel类型以最小化头开销。</p><p>通常，算子工程会通过算子使用的指令自动识别算子类型，但该功能无法区分AIC和AIV的配比，默认按照AIV:AIC为1:2的配比下发任务。此外，自动识别功能可能失效，因为其依赖于编译优化的结果。所以推荐用户手动设置算子的Kernel类型。具体设置方法请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E8%AE%BE%E7%BD%AEKernel%E7%B1%BB%E5%9E%8B.md" target="_blank" rel="noreferrer">设置Kernel类型</a>。</p></li></ul>',7)])])}const m=t(i,[["render",a]]);export{E as __pageData,m as default};
